// The tombstone serve law's store side (tombstone-lifecycle 3.2):
// QueryItemsBySeries excludes deleted rows in BOTH backing legs, while
// QueryItems' empty status keeps meaning no-filter — the store invariant the
// api's default exclusion is layered on.

// tombstoneItemRow soft-deletes a seeded row the way the sweep does: PutItem
// keyed on the same file_id, status flipped, the document bytes passed back.
func tombstoneItemRow(t *testing.T, s *Store, id string) {
	t.Helper()
	ctx := context.Background()
	it, err := s.GetItem(ctx, id, access.System())
	if err != nil {
		t.Fatalf("GetItem %s: %v", id, err)
	}
	it.Status = "deleted"
	if err := s.PutItem(ctx, it); err != nil {
		t.Fatalf("PutItem tombstone %s: %v", id, err)
	}
}

// TestQueryItemsBySeriesSkipsDeleted pins the store-level exclusion on the
// series episode read: the directory leg and the file leg BOTH drop deleted
// rows — episode lists and the next-episode pick never see a dead row.
func TestQueryItemsBySeriesSkipsDeleted(t *testing.T) {
	s := openSeriesStore(t)
	ctx := context.Background()

	putItem := func(rel string) {
		t.Helper()
		if err := s.PutItem(ctx, Item{
			ID: "itm_ts_" + rel, ModuleID: "serial", LibraryID: 3,
			FileID: rel, RelativePath: rel, MediaType: "serial",
			Document:      json.RawMessage(`{"parsed":{"series_relative_path":"Show"},"ffprobe":{}}`),
			SchemaVersion: 1, Status: "ready",
		}); err != nil {
			t.Fatalf("PutItem %s: %v", rel, err)
		}
	}
	for _, rel := range []string{"Show/E01.mkv", "Show/E02.mkv", "loose.mkv"} {
		putItem(rel)
	}
	dirSeries := Series{ID: wantSeriesID(3, "Show"), ModuleID: "serial", LibraryID: 3, RelativePath: "Show"}
	fileSeries := Series{ID: wantSeriesID(3, "loose.mkv"), ModuleID: "serial", LibraryID: 3, RelativePath: "loose.mkv"}

	t.Run("file_leg_keeps_live_row", func(t *testing.T) {
		items, err := s.QueryItemsBySeries(ctx, fileSeries, SeriesBackingFile, access.System())
		if err != nil {
			t.Fatalf("QueryItemsBySeries(file): %v", err)
		}
		if len(items) != 1 || items[0].RelativePath != "loose.mkv" {
			t.Fatalf("episodes = %v, want exactly loose.mkv", rels(items))
		}
	})

	tombstoneItemRow(t, s, "itm_ts_Show/E02.mkv")

	t.Run("directory_leg_drops_dead", func(t *testing.T) {
		items, err := s.QueryItemsBySeries(ctx, dirSeries, SeriesBackingDirectory, access.System())
		if err != nil {
			t.Fatalf("QueryItemsBySeries(directory): %v", err)
		}
		got := rels(items)
		if len(got) != 1 || got[0] != "Show/E01.mkv" {
			t.Fatalf("episodes = %v, want exactly [Show/E01.mkv] — the tombstoned E02 must drop", got)
		}
	})

	tombstoneItemRow(t, s, "itm_ts_loose.mkv")

	t.Run("file_leg_drops_dead", func(t *testing.T) {
		items, err := s.QueryItemsBySeries(ctx, fileSeries, SeriesBackingFile, access.System())
		if err != nil {
			t.Fatalf("QueryItemsBySeries(file): %v", err)
		}
		if items == nil || len(items) != 0 {
			t.Fatalf("episodes = %v, want non-nil empty — the tombstoned episode must drop", items)
		}
	})
}

// TestQueryItemsEmptyStatusReadsAllStatuses pins THE store invariant the
// serve law preserves: an empty status is no-filter — rows of EVERY status,
// tombstoned ones included — and an explicit status keeps exact match.
func TestQueryItemsEmptyStatusReadsAllStatuses(t *testing.T) {
	s := openSeriesStore(t)
	ctx := context.Background()

	put := func(rel, status string) {
		t.Helper()
		if err := s.PutItem(ctx, Item{
			ID: "itm_inv_" + rel, ModuleID: "serial", LibraryID: 3,
			FileID: rel, RelativePath: rel, MediaType: "serial",
			Document:      json.RawMessage(`{"parsed":{},"ffprobe":{}}`),
			SchemaVersion: 1, Status: status,
		}); err != nil {
			t.Fatalf("PutItem %s: %v", rel, err)
		}
	}
	put("a_new.mkv", "new")
	put("b_ready.mkv", "ready")
	put("c_deleted.mkv", "deleted")

	items, err := s.QueryItems(ctx, 3, "", "", false, 50, 0, access.System())
	if err != nil {
		t.Fatalf("QueryItems(empty status): %v", err)
	}
	statuses := map[string]bool{}
	for _, it := range items {
		statuses[it.Status] = true
	}
	for _, want := range []string{"new", "ready", "deleted"} {
		if !statuses[want] {
			t.Fatalf("empty-status read missed status %q (got %v) — the no-filter invariant is broken", want, statuses)
		}
	}

	tomb := "c_deleted.mkv"
	items, err = s.QueryItems(ctx, 3, "deleted", "", false, 50, 0, access.System())
	if err != nil {
		t.Fatalf("QueryItems(deleted): %v", err)
	}
	if len(items) != 1 || items[0].RelativePath != tomb {
		t.Fatalf("exact-match deleted = %v, want exactly [%s]", rels(items), tomb)
	}
}
